#!/usr/bin/env python3
"""STYLE-RULES R49 (Steven, Oct 18 12:39 AM / 12:41 AM / 12:43 AM): the ONE shared page-listen script (between
<!-- ph-page-listen:start --> / <!-- ph-page-listen:end -->) used by every generated email copy, notice page and report page
with a 'ph-listen' button. It reads all visible content in page order, including the closing source / credit line.
Generators (notice_listen.py, notice_page.py, make_live_preview.py) take SCRIPT from here; `apply()` swaps an older block
for this one. Checked by scripts/check_listen_coverage.py.
Usage: python3 scripts/page_listen.py PAGE.html [...]   (rewrites the block in place; prints changed/unchanged)"""
import re, sys
START, END = "<!-- ph-page-listen:start -->", "<!-- ph-page-listen:end -->"
SCRIPT = "<!-- ph-page-listen:start -->\n<script>\n(() => {\n  const link = document.querySelector('a.ph-listen');\n  if (!link) return;\n  const label = Array.from(link.childNodes).find((n) => n.nodeType === 3 && n.textContent.trim());\n  if (!('speechSynthesis' in window) || !('SpeechSynthesisUtterance' in window)) {\n    return;\n  }\n  const synth = window.speechSynthesis;\n  const MON = {Jan:'January',Feb:'February',Mar:'March',Apr:'April',Jun:'June',Jul:'July',Aug:'August',Sep:'September',Oct:'October',Nov:'November',Dec:'December'};\n  let run = 0, playing = false, started = false;\n  const setLabel = (t) => { if (label) label.textContent = t; link.setAttribute('aria-label', t === 'Stop' ? 'Stop reading' : 'Listen to this page'); };\n  function chunks(text) {\n    const clean = text.replace(/\\b(Jan|Feb|Mar|Apr|Jun|Jul|Aug|Sep|Oct|Nov|Dec)\\b\\.?/g, (m, k) => MON[k]).replace(/\\s+/g, ' ').trim();\n    if (!clean) return [];\n    const frags = typeof Intl.Segmenter === 'function'\n      ? Array.from(new Intl.Segmenter('en-US', {granularity: 'sentence'}).segment(clean), (s) => s.segment.trim()).filter(Boolean)\n      : [clean];\n    const out = []; let p = '';\n    for (const s of frags) { if (p && p.length + s.length + 1 > 260) { out.push(p); p = s; } else p += (p ? ' ' : '') + s; }\n    if (p) out.push(p);\n    return out;\n  }\n  function parts() {\n    // R49 (Steven, Oct 18 12:39/12:43 AM): read ALL visible content in page order -- the h1, every content card / email\n    // row (paragraphs, quotes, lists, tables inside), and the source / credit line at the end. Skipped: the email's\n    // Subject/From/Sent header row, attachment lists, navigation and the Listen button itself.\n    const h1 = document.querySelector('h1');\n    const sel = 'main .content-card, main .ph-row, main .source, main .ph-source, main .credit, main .byline';\n    const all = Array.from(document.querySelectorAll(sel))\n      .filter((el) => !el.closest('nav, .ph-strip, .ph-links') && !el.classList.contains('attachments') && !/^\\s*Subject:/.test(el.innerText));\n    const blocks = all.filter((el) => !all.some((o) => o !== el && o.contains(el)))\n      .map((el) => el.innerText.trim())\n      .filter(Boolean);\n    return [h1 ? h1.textContent : '', ...blocks].flatMap((t) => t.split(/\\n+/)).flatMap(chunks);  // each visual line its own phrase\n  }\n\n  function stop() { run += 1; playing = false; synth.cancel(); setLabel('Listen'); }\n  function start(auto) {\n    const list = parts(); const me = ++run; let i = 0;\n    synth.cancel(); playing = true; started = false; setLabel('Stop');\n    const next = () => {\n      if (me !== run) return;\n      if (i >= list.length) { playing = false; setLabel('Listen'); return; }\n      const u = new SpeechSynthesisUtterance(list[i]);\n      u.lang = 'en-US'; u.rate = 1;\n      u.onstart = () => { if (me === run) started = true; };\n      u.onend = () => { if (me !== run) return; i += 1; next(); };\n      u.onerror = (e) => { if (me !== run || e.error === 'canceled' || e.error === 'interrupted') return; stop(); };\n      synth.speak(u);\n    };\n    next();\n    if (auto) window.setTimeout(() => { if (me === run && playing && !started) { stop(); arm(); } }, 4000);\n  }\n  link.addEventListener('click', (e) => { e.preventDefault(); if (playing) stop(); else start(false); });\n  function arm() {\n    const onTap = (e) => {\n      document.removeEventListener('click', onTap, true);\n      if (playing || (e.target.closest && e.target.closest('a'))) return;\n      start(false);\n    };\n    document.addEventListener('click', onTap, true);\n  }\n  window.addEventListener('pagehide', stop);\n  const q = new URLSearchParams(location.search);\n  if (q.get('listen') === '1' || q.get('autoplay') === '1') {\n    const go = () => start(true);\n    if (document.readyState === 'complete') window.setTimeout(go, 0); else window.addEventListener('load', go, {once: true});\n  }\n})();\n</script>\n<!-- ph-page-listen:end -->\n"
BUTTON_SOURCE = "pages/2026-10-09-weekly-manager-update.html"  # the standard speaker + 'Listen' button markup
def apply(t):
    if START not in t: return t
    a = t.index(START); b = t.index(END, a) + len(END)
    return t[:a] + SCRIPT.strip() + t[b:]
def apply_file(path):
    t = open(path, encoding="utf-8").read(); n = apply(t)
    if n != t: open(path, "w", encoding="utf-8").write(n); return True
    return False
if __name__ == "__main__":
    for f in sys.argv[1:]: print(("updated " if apply_file(f) else "unchanged ") + f)
    sys.path.insert(0, __import__("os").path.dirname(__file__)); import check_listen_coverage as _lc; _lc.require(sys.argv[1:])  # R49 required step
